import assert from "node:assert/strict";

export function summarizeTasks(tasks) {
  if (!Array.isArray(tasks)) throw new TypeError("Expected an array");
  const groups = new Map();
  for (const task of tasks) {
    if (!task || typeof task.owner !== "string" || !task.owner.trim() || typeof task.done !== "boolean") {
      throw new TypeError("Invalid task");
    }
    const owner = task.owner.trim();
    const previous = groups.get(owner) ?? { owner, total: 0, completed: 0 };
    groups.set(owner, { ...previous, total: previous.total + 1, completed: previous.completed + Number(task.done) });
  }
  return [...groups.values()].sort((a, b) => a.owner < b.owner ? -1 : a.owner > b.owner ? 1 : 0);
}
const tasks = Object.freeze([
  Object.freeze({ owner: "Ada", done: true }),
  Object.freeze({ owner: "Bo", done: true }),
  Object.freeze({ owner: "Ada", done: false }),
]);
assert.deepEqual(summarizeTasks([]), []);
assert.deepEqual(summarizeTasks([{ owner: "__proto__", done: false }]), [{ owner: "__proto__", total: 1, completed: 0 }]);
assert.throws(() => summarizeTasks([{ owner: "Ada", done: "yes" }]), TypeError);
console.log(JSON.stringify(summarizeTasks(tasks)));
assert.equal(summarizeTasks([{ owner: "Ada", done: false }])[0].completed, 0);

