import assert from "node:assert/strict";

const events = [];

// Adapter-shaped operation: honours signal and stops early when aborted.
async function slowOperation(signal, label, durationMs) {
  events.push("start:" + label);
  return new Promise((resolve, reject) => {
    const work = setTimeout(() => {
      cleanup();
      events.push("finished:" + label);
      resolve(label + ":done");
    }, durationMs);
    const onAbort = () => {
      cleanup();
      events.push("aborted:" + label);
      reject(signal.reason);
    };
    const cleanup = () => {
      clearTimeout(work);
      signal.removeEventListener("abort", onAbort);
      events.push("released:" + label);
    };
    if (signal.aborted) onAbort();
    else signal.addEventListener("abort", onAbort, { once: true });
  });
}

// Case 1: external cancel via controller.abort() before the work finishes.
const controller = new AbortController();
const first = slowOperation(controller.signal, "external", 50);
setTimeout(() => controller.abort(new Error("cancelled by user")), 10);
try { await first; assert.fail("must reject"); }
catch (error) { events.push("caught:" + error.message); }

// Case 2: bounded request via AbortSignal.timeout; the slow work loses the race.
const timeoutSignal = AbortSignal.timeout(20);
try { await slowOperation(timeoutSignal, "timeout", 80); assert.fail("must reject"); }
catch (error) { events.push("caught:" + error.name + "/" + error.message); }

// Case 3: operation completes before the deadline; cleanup still runs.
const okSignal = AbortSignal.timeout(500);
events.push(await slowOperation(okSignal, "ok", 5));

// Case 4: a controller aborted synchronously never starts the work.
const dead = new AbortController();
dead.abort(new Error("already closed"));
try { await slowOperation(dead.signal, "dead", 50); assert.fail("must reject"); }
catch (error) { events.push("caught:" + error.message); }

console.log(events.join("\n"));

assert.equal(events.filter(e => e.startsWith("released:")).length, 4);
assert.ok(events.includes("finished:ok"));
assert.ok(!events.includes("finished:external"));
assert.ok(!events.includes("aborted:ok"));

