import assert from "node:assert/strict";

const waits = [];
const sleep = async (ms) => { waits.push(ms); };

// Deterministic jitter: a counter-based spread instead of Math.random().
const makeJitter = (spreadMs) => {
  let n = 0;
  return () => { n = (n + 1) % 4; return n * spreadMs; };
};

const backoff = (attempt, { baseMs, capMs, jitter }) =>
  Math.min(baseMs * 2 ** attempt, capMs) + jitter();

class TransientError extends Error {}
class FatalError extends Error {}

async function retry(operation, options) {
  const { attempts, baseMs, capMs, jitter, retryOn } = options;
  let attempt = 0;
  for (;;) {
    try {
      return await operation(attempt);
    } catch (error) {
      const lastAttempt = attempt + 1 >= attempts;
      if (lastAttempt || !retryOn(error)) throw error;
      await sleep(backoff(attempt, { baseMs, capMs, jitter }));
      attempt += 1;
    }
  }
}

const log = [];
const report = (label, value) => log.push(label + " -> " + value);

// Case 1: two retryable failures, then success.
let calls = 0;
const flaky = async () => {
  calls += 1;
  if (calls < 3) throw new TransientError("TRANSIENT_" + calls);
  return "recovered";
};
report("flaky", await retry(flaky, { attempts: 5, baseMs: 100, capMs: 400, jitter: makeJitter(25), retryOn: e => e instanceof TransientError }));
report("flakyCalls", calls);

// Case 2: fatal errors are never retried.
let fatalCalls = 0;
try {
  await retry(async () => { fatalCalls += 1; throw new FatalError("BAD_REQUEST"); },
    { attempts: 5, baseMs: 100, capMs: 400, jitter: makeJitter(25), retryOn: e => e instanceof TransientError });
} catch (error) { report("fatal", error.constructor.name + ":" + error.message); }
report("fatalCalls", fatalCalls);

// Case 3: budget exhaustion rethrows the last error.
let alwaysCalls = 0;
try {
  await retry(async () => { alwaysCalls += 1; throw new TransientError("DOWN_" + alwaysCalls); },
    { attempts: 3, baseMs: 100, capMs: 400, jitter: makeJitter(25), retryOn: e => e instanceof TransientError });
} catch (error) { report("exhausted", error.message); }
report("exhaustedCalls", alwaysCalls);

report("waits", waits.join(","));

console.log(log.join("\n"));

assert.equal(waits.join(","), "125,250,125,250");
assert.equal(calls, 3);
assert.equal(fatalCalls, 1);
assert.equal(alwaysCalls, 3);

