// Fake clock: deterministic time control without real timers.
function createClock() {
  let now = 0;
  let handle = 0;
  const tasks = new Map();
  return {
    now: () => now,
    setTimeout(fn, ms) { handle += 1; tasks.set(handle, { at: now + ms, fn }); return handle; },
    clearTimeout(id) { tasks.delete(id); },
    advance(ms) {
      const target = now + ms;
      for (;;) {
        let dueId = null;
        let dueAt = Infinity;
        for (const [id, task] of tasks) if (task.at <= target && task.at < dueAt) { dueAt = task.at; dueId = id; }
        if (dueId === null) break;
        const task = tasks.get(dueId);
        tasks.delete(dueId);
        now = task.at;
        task.fn();
      }
      now = target;
    },
  };
}

function debounce(fn, waitMs, clock) {
  let timerId = null;
  return (...args) => {
    if (timerId !== null) clock.clearTimeout(timerId);
    timerId = clock.setTimeout(() => { timerId = null; fn(...args); }, waitMs);
  };
}

function throttle(fn, intervalMs, clock) {
  let lastCall = null;
  let timerId = null;
  return (...args) => {
    const elapsed = lastCall === null ? Infinity : clock.now() - lastCall;
    if (elapsed >= intervalMs) {
      lastCall = clock.now();
      fn(...args);
    } else if (timerId === null) {
      timerId = clock.setTimeout(() => {
        timerId = null;
        lastCall = clock.now();
        fn(...args);
      }, intervalMs - elapsed);
    }
  };
}

function memoize(fn, keyOf = JSON.stringify) {
  const cache = new Map();
  const wrapped = (value) => {
    const key = keyOf(value);
    if (!cache.has(key)) cache.set(key, fn(value));
    return cache.get(key);
  };
  wrapped.cache = cache;
  return wrapped;
}

