// Unit under test with four distinct branches.
const branches = { low: 0, high: 0, inRange: 0, throws: 0 };
function normalizeScore(raw) {
  if (typeof raw !== "number" || !Number.isFinite(raw)) {
    branches.throws += 1;
    throw new TypeError("Expected a finite number");
  }
  if (raw < 0) { branches.low += 1; return 0; }
  if (raw > 100) { branches.high += 1; return 100; }
  branches.inRange += 1;
  return Math.round(raw);
}

// Minimal deterministic runner: same shape as node:test blocks,
// but with a stable transcript (node --test prints timings per run).
const results = [];
async function runTests(tests) {
  for (const { name, fn } of tests) {
    try { await fn(); results.push("pass:" + name); }
    catch (error) { results.push("fail:" + name + ":" + String(error.message).split("\n")[0]); }
  }
}
const test = (name, fn) => ({ name, fn });

const tests = [
  test("clamp keeps values inside 0..100", () => {
    const table = [
      { raw: -5, expected: 0 },
      { raw: 0, expected: 0 },
      { raw: 100, expected: 100 },
      { raw: 120, expected: 100 },
    ];
    for (const { raw, expected } of table) assert.equal(normalizeScore(raw), expected);
  }),
  test("rounding uses Math.round semantics", () => {
    assert.equal(normalizeScore(50.4), 50);
    assert.equal(normalizeScore(50.5), 51);
  }),
  test("invalid input is rejected, not coerced", () => {
    assert.throws(() => normalizeScore(NaN), TypeError);
    assert.throws(() => normalizeScore("90"), TypeError);
  }),
  test("failures are recorded with their message", () => {
    assert.ok(false, "expected mismatch");
  }),
];

await runTests(tests);

